<?php
/**
 * Editor script dependencies for the login button block.
 *
 * WordPress reads this file (generated by @wordpress/scripts in
 * build-based plugins; maintained by hand here because this plugin
 * has no build step) to register the block's editor script with the
 * dependencies index.js actually uses. Without it, the script is
 * registered with no dependencies and loads before wp-blocks
 * exists, so the block never registers in the editor.
 *
 * @package AgentKeySignIn
 */

return array(
	'dependencies' => array( 'wp-blocks', 'wp-element', 'wp-block-editor', 'wp-components', 'wp-server-side-render', 'wp-i18n' ),
	'version'      => '0.1.5',
);
